const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

Given('the app is loaded', function () {
  // App is loaded by Before hook in world.js
});

Given('a todo {string} exists', function (title) {
  const stored = this.window.localStorage.getItem('todos-vanilla');
  const todos = stored ? JSON.parse(stored) : [];
  todos.push({ id: todos.length + 1, title: title, completed: false });
  this.window.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  // Reload from localStorage and re-render
  this.window.eval('load(); render()');
});

Given('a completed todo {string} exists', function (title) {
  const stored = this.window.localStorage.getItem('todos-vanilla');
  const todos = stored ? JSON.parse(stored) : [];
  todos.push({ id: todos.length + 1, title: title, completed: true });
  this.window.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.window.eval('load(); render()');
});

Given('the following todos exist:', function (dataTable) {
  const rows = dataTable.hashes();
  const todos = [];
  let id = 1;
  rows.forEach(row => {
    todos.push({ id: id++, title: row.title, completed: row.completed === 'true' });
  });
  this.window.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
  this.window.eval('load(); render()');
});

When('the user types {string} in the new-todo input and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, bubbles: true }));
});

When('the user toggles the checkbox for todo {string}', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const checkbox = li.querySelector('.toggle');
      checkbox.checked = !checkbox.checked;
      checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
      break;
    }
  }
});

When('the user clicks the toggle-all checkbox', function () {
  const checkbox = this.document.getElementById('toggle-all');
  checkbox.checked = !checkbox.checked;
  checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user destroys the todo {string}', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const destroyBtn = li.querySelector('.destroy');
      destroyBtn.click();
      break;
    }
  }
});

When('the user double-clicks the label of todo {string}', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
      break;
    }
  }
});

When('the user types {string} in the edit input and presses Enter', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, bubbles: true }));
});

When('the user types {string} in the edit input and presses Enter on blur', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the user types {string} in the edit input and presses Escape', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 27, bubbles: true }));
});

When('the user clears the edit input and presses Enter', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, bubbles: true }));
});

When('the page is reloaded', function () {
  this.loadApp();
});

When('the user clicks the clear-completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.click();
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

